(function(){'use strict';
const KEY='nawaf-hq-v5',$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason='v23'){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason}}))}
function retryTask(id){const s=read(),t=(s.tasks||[]).find(x=>x.id===id);if(!t)return;t.lastFailure={reason:t.blockedReason||'تعثر سابق',at:t.executionFinishedAt||new Date().toISOString()};t.status='READY';t.progress=0;t.updatedAt=new Date().toISOString();delete t.blockedReason;delete t.blockerType;delete t.requiredTools;delete t.executionStartedAt;write(s,'v23-retry');document.querySelector('#v23-modal')?.classList.remove('show');setTimeout(()=>window.NawafAgents?.runTask?.(id).catch(()=>{}),200)}
function modal(title,html){let m=$('#v23-modal');if(!m){m=document.createElement('div');m.id='v23-modal';m.className='v23-modal';m.innerHTML='<div class="v23-dialog"><header><div><span>NAWAF HQ V23</span><h2></h2></div><button>×</button></header><main></main></div>';document.body.appendChild(m);m.onclick=e=>{if(e.target===m||e.target.closest('header button'))m.classList.remove('show')}}m.querySelector('h2').textContent=title;m.querySelector('main').innerHTML=html;m.classList.add('show');return m}
function evidence(t){return Array.isArray(t.evidence)?t.evidence:(Array.isArray(t.aiResult?.evidence)?t.aiResult.evidence:[])}
function gate(t){if(t.status!=='COMPLETED')return {ok:false,label:'غير مكتمل'};const ev=evidence(t);if(!ev.length)return {ok:false,label:'بدون دليل'};if(/QA|فحص|اختبار|REVIEW/i.test((t.kind||'')+' '+(t.title||''))&&!ev.length)return {ok:false,label:'QA ناقص'};return {ok:true,label:'موثّق'}}
async function health(){try{const r=await fetch('/api/health',{cache:'no-store'}),j=await r.json();return {ok:r.ok&&j.ok,data:j}}catch(e){return {ok:false,error:e.message}}}
async function integrations(){const m=modal('مركز الاتصالات','<div class="v23-loading">جاري فحص الاتصالات الحقيقية…</div>'),[h,tr]=await Promise.all([health(),fetch('/api/trading/status',{cache:'no-store'}).then(async r=>({ok:r.ok,data:await r.json().catch(()=>({}))})).catch(()=>({ok:false,data:{}}))]),d=h.data||{},engine=d.engine||{},s=read(),pending=(s.connectionRequests||[]).filter(x=>['PENDING','APPROVED'].includes(x.status));const rows=[['محرك الشركة',h.ok],['Cloud State',!!d.cloudState],['Slack',!!d.slack],['Project Execution',!!d.projectExecution],['Gemini',engine.gemini==='CONNECTED'],['GitHub',/CONNECTED|READY|OK/i.test(String(engine.githubPrivateRepo||''))],['Paper Trading',tr.ok&&tr.data?.ok!==false]];m.querySelector('main').innerHTML='<div class="v23-grid">'+rows.map(([n,ok])=>'<article><b>'+esc(n)+'</b><span class="'+(ok?'ok':'off')+'">'+(ok?'متصل':'غير مؤكد')+'</span></article>').join('')+'</div><div class="v23-list">'+pending.slice(0,12).map(x=>'<article><span><b>'+esc(x.tool||x.provider||'طلب اتصال')+'</b><small>'+esc(x.reason||x.note||'بانتظار الربط')+'</small></span><strong>'+esc(x.status)+'</strong></article>').join('')+'</div><p class="v23-note">الحالة من فحص النظام الفعلي؛ لا يتم عرض اتصال وهمي.</p>'}
function qa(){const s=read(),done=(s.tasks||[]).filter(t=>t.status==='COMPLETED'),bad=done.filter(t=>!gate(t).ok);modal('QA Gate',`<div class="v23-kpis"><div><b>${done.length}</b><span>مكتملة</span></div><div><b>${done.length-bad.length}</b><span>موثقة</span></div><div><b>${bad.length}</b><span>تحتاج دليل</span></div></div><div class="v23-list">${done.slice(0,30).map(t=>`<article><span><b>${esc(t.title)}</b><small>${esc((t.employeeId||'')+' • '+evidence(t).length+' دليل')}</small></span><strong class="${gate(t).ok?'ok':'off'}">${gate(t).label}</strong></article>`).join('')||'<p>لا توجد مهام مكتملة بعد.</p>'}</div>`)}
function timeline(){const s=read(),events=[];(s.activity||[]).forEach(a=>events.push({at:a.at,text:a.text,type:a.type||'ACTIVITY'}));(s.tasks||[]).forEach(t=>{if(t.createdAt)events.push({at:t.createdAt,text:'إنشاء: '+t.title,type:'TASK'});if(t.executionStartedAt)events.push({at:t.executionStartedAt,text:'بدأ التنفيذ: '+t.title,type:'RUN'});if(t.executionFinishedAt)events.push({at:t.executionFinishedAt,text:'انتهى التنفيذ: '+t.title,type:t.status})});events.sort((a,b)=>Date.parse(b.at||0)-Date.parse(a.at||0));modal('Timeline الحقيقي','<div class="v23-timeline">'+events.slice(0,80).map(e=>'<article><time>'+esc(new Date(e.at).toLocaleString('ar-SA'))+'</time><b>'+esc(e.text)+'</b><small>'+esc(e.type)+'</small></article>').join('')+'</div>')}
function recovery(){const s=read(),bad=(s.tasks||[]).filter(t=>['BLOCKED','BLOCKED_BY_TOOL','PAUSED'].includes(t.status)||t.lastFailure),m=modal('Recovery Center','<div class="v23-list">'+bad.slice(0,40).map(t=>'<article><span><b>'+esc(t.title)+'</b><small>'+esc(t.blockedReason||t.lastFailure?.reason||'تعثر سابق محفوظ')+'</small></span><button data-v23-retry="'+esc(t.id)+'">إعادة محاولة</button></article>').join('')+' </div><p class="v23-note">إعادة المحاولة تعيد المهمة إلى READY ثم ترسلها للمحرك؛ لا تعتبر نجاحًا إلا بعد نتيجة وأدلة.</p>');m.querySelectorAll('[data-v23-retry]').forEach(b=>b.onclick=()=>retryTask(b.dataset.v23Retry))}
function approvals(){if(window.NawafHQV13?.openCenter)return window.NawafHQV13.openCenter();const s=read(),items=[...(s.approvals||[]),...(s.tasks||[]).filter(t=>t.status==='WAITING_FOR_NAWAF').map(t=>({id:'task:'+t.id,taskId:t.id,title:t.title,reason:t.blockedReason||'يحتاج قرارك',type:'TASK'}))];modal('صندوق الموافقات',`<div class="v23-kpis"><div><b>${items.length}</b><span>بانتظارك</span></div><div><b>${(s.tasks||[]).filter(t=>t.status==='WAITING_FOR_CONNECTION').length}</b><span>ربط أدوات</span></div><div><b>${(s.tasks||[]).filter(t=>t.status==='BLOCKED_BY_TOOL').length}</b><span>متعثر</span></div></div><div class="v23-list">${items.slice(0,40).map(a=>`<article><span><b>${esc(a.title||a.action||'موافقة')}</b><small>${esc(a.reason||a.details||a.status||'بانتظار القرار')}</small></span><strong>${esc(a.type||'APPROVAL')}</strong></article>`).join('')||'<p>ما عندك موافقات معلقة.</p>'}</div><p class="v23-note">مركز عرض احتياطي فقط؛ الإجراءات الفعلية تستخدم مركز قرارات نواف.</p>`)}
function ceoMobile(){const s=read(),active=(s.tasks||[]).filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status)),waiting=(s.tasks||[]).filter(t=>t.status==='WAITING_FOR_NAWAF'),blocked=(s.tasks||[]).filter(t=>t.blockedReason&&t.status!=='COMPLETED');modal('CEO Mobile',`<div class="v23-kpis"><div><b>${active.length}</b><span>يعمل الآن</span></div><div><b>${waiting.length}</b><span>قرارات</span></div><div><b>${blocked.length}</b><span>متعثر</span></div></div><div class="v23-list">${[...waiting,...blocked,...active].slice(0,20).map(t=>`<article><span><b>${esc(t.title)}</b><small>${esc(t.blockedReason||t.status)}</small></span><strong>${esc(t.status)}</strong></article>`).join('')||'<p>الوضع هادئ حاليًا.</p>'}</div><p class="v23-note">واجهة مختصرة للقرارات والحالة التشغيلية على الجوال والتابلت.</p>`)}
function costs(){const s=read(),runs=(s.tasks||[]).filter(t=>t.lastRunAt||t.executionStartedAt),failed=(s.tasks||[]).filter(t=>['BLOCKED','BLOCKED_BY_TOOL'].includes(t.status));modal('مركز الاستخدام',`<div class="v23-kpis"><div><b>${runs.length}</b><span>تشغيلات</span></div><div><b>${failed.length}</b><span>تعثر</span></div><div><b>0 ر.س</b><span>تكلفة مؤكدة مسجلة</span></div></div><p class="v23-note">لا يعرض HQ أرقام توكنز أو فواتير تقديرية على أنها حقيقية. أي تكلفة فعلية تحتاج بيانات موثقة من المزود المتصل.</p>`)}
function memory(){return window.NawafCompanyOS?.projectMemory?.()||document.querySelector('[data-v15="memory"]')?.click()}
function morning(){return document.querySelector('[data-v15="brief"]')?.click()||window.NawafExecutiveSecretary?.open?.()}
function finance(){return window.NawafFinance?.paper?.()||window.NawafFinance?.open?.()}
function mount(){if($('#v23-launcher'))return;const x=document.createElement('section');x.id='v23-launcher';x.innerHTML='<button data-v23="approvals">الموافقات</button><button data-v23="integrations">الاتصالات</button><button data-v23="qa">QA Gate</button><button data-v23="timeline">Timeline</button><button data-v23="memory">ذاكرة المشاريع</button><button data-v23="finance">المركز المالي</button><button data-v23="recovery">Recovery</button><button data-v23="costs">الاستخدام</button><button data-v23="mobile">CEO Mobile</button><button data-v23="morning">Morning Brief</button>';document.body.appendChild(x);x.onclick=e=>{const b=e.target.closest('[data-v23]');if(!b)return;({approvals,integrations,qa,timeline,memory,finance,recovery,costs,mobile:ceoMobile,morning}[b.dataset.v23]||(()=>{}))()}}
function truth(){document.querySelectorAll('[data-task]').forEach(el=>{const id=el.dataset.task,t=(read().tasks||[]).find(x=>x.id===id);if(!t||t.status!=='COMPLETED')return;el.dataset.verified=gate(t).ok?'1':'0';el.title=gate(t).ok?'مكتمل بأدلة':'مكتمل في الحالة لكن يحتاج دليل تحقق'})}
function boot(){mount();truth()}window.addEventListener('nawaf:state-updated',()=>setTimeout(truth,80));setInterval(boot,5000);document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();window.NawafHQV23={approvals,integrations,qa,timeline,recovery,costs,ceoMobile};})();